        let m = 27;
        let mut valid = HashSet::new();
        let mut f = vec![0; m];

        for i in 0..m {
            if Self::f1(i as i32) {
                valid.insert(i as i32);
                f[i] = 1;
            }
        }

        let mut d: HashMap<i32, Vec<i32>> = HashMap::new();
        for &i in &valid {
            for &j in &valid {
                if Self::f2(i, j) {
                    d.entry(i).or_insert_with(Vec::new).push(j);
